import {request} from 'node:https';
import {readFile} from 'node:fs/promises';

// A short-lived localhost-only certificate is generated by the native E2E
// server. Trust ONLY that exact certificate for Node's control requests.
// Never disable TLS verification for the whole process or provider calls.
export async function pinnedLocalRequest(url,{method='GET',body,certificatePath,timeout=45000}={}){
  const target=new URL(url);
  if(target.protocol!=='https:'||target.hostname!=='localhost')
    throw new Error('Pinned E2E HTTPS is restricted to localhost');
  if(typeof certificatePath!=='string'||!certificatePath)
    throw new Error('Pinned E2E HTTPS requires a server certificate');
  const ca=await readFile(certificatePath);
  const payload=body===undefined?undefined:JSON.stringify(body);
  return new Promise((resolve,reject)=>{
    const req=request(target,{method,ca,rejectUnauthorized:true,timeout,
      headers:payload===undefined?undefined:{'content-type':'application/json'}},res=>{
      const chunks=[];let bytes=0;
      res.on('data',chunk=>{bytes+=chunk.length;if(bytes>1024*1024){req.destroy(new Error('Pinned E2E response exceeded 1 MiB'));return}chunks.push(chunk)});
      res.on('end',()=>resolve({status:res.statusCode,text:Buffer.concat(chunks).toString('utf8')}));
      res.on('error',reject);
    });
    req.on('timeout',()=>req.destroy(new Error('Pinned E2E HTTPS request timed out')));
    req.on('error',reject);
    req.end(payload);
  });
}
